00064 /* print function ************************************************************/
00065 #if _WIN32
00066 #define print(args, ...) printf(args, __VA_ARGS__)
00067 #else
00068 #define print(args...) printf(args)
00069 #endif
00070 
00071 #define VERBOSE_0                  0
00072 #define VERBOSE_1                  1
00073 #define VERBOSE_2                  2
00074 
00075 static int op_verbose = VERBOSE_2;
00076 
00077 #if _WIN32
00078 #define v0print(args,...) {if(op_verbose >= VERBOSE_0){print(args,__VA_ARGS__);}}
00079 #define v1print(args,...) {if(op_verbose >= VERBOSE_1){print(args,__VA_ARGS__);}}
00080 #define v2print(args,...) {if(op_verbose >= VERBOSE_2){print(args,__VA_ARGS__);}}
00081 #else
00082 #define v0print(args...) {if(op_verbose >= VERBOSE_0) {print(args);}}
00083 #define v1print(args...) {if(op_verbose >= VERBOSE_1) {print(args);}}
00084 #define v2print(args...) {if(op_verbose >= VERBOSE_2) {print(args);}}
00085 #endif
00086 /****************************************************************************/
00087 #if _WIN32
00088 #include <windows.h>
