00090 #define EVC_CLK             DWORD
00091 #define EVC_CLK_PER_SEC     (1000)
00092 #define EVC_CLK_PER_MSEC    (1)
00093 #define EVC_CLK_MAX         ((EVC_CLK)(-1))
00094 #if USE_CPU_TIME_CLOCK
00095 #define evc_clk_get()       clock()
00096 #else
00097 #define evc_clk_get()       GetTickCount()
00098 #endif
00099 /****************************************************************************/
00100 #elif __linux__ || __CYGWIN__
00101 #include <time.h>
00102 #include <sys/time.h>
00103 #define EVC_CLK             unsigned long
00104 #define EVC_CLK_MAX         ((EVC_CLK)(-1))
00105 #define EVC_CLK_PER_SEC     (10000)
00106 #define EVC_CLK_PER_MSEC    (10)
00107 static EVC_CLK evc_clk_get(void)
00108 {
00109     EVC_CLK clk;
00110 #if USE_CPU_TIME_CLOCK
00111     clk = (EVC_CLK)(clock()) * 10000L / CLOCKS_PER_SEC;
00112 #else
00113     struct timeval t;
00114     gettimeofday(&t, NULL);
00115     clk = t.tv_sec*10000L + t.tv_usec/100L;
00116 #endif
00117     return clk;
00118 }
00119 /* The others ***************************************************************/
00120 #else
00121 #error THIS PLATFORM CANNOT SUPPORT CLOCK
00122 #endif
00123 
00124 #define evc_clk_diff(t1, t2) \
00125     (((t2) >= (t1)) ? ((t2) - (t1)) : ((EVC_CLK_MAX - (t1)) + (t2)))
00126 #if REMOVE_WARNING
00127 EVC_CLK evc_clk_from(EVC_CLK from) \
00128 {
00129   EVC_CLK now = evc_clk_get(); \
00130     return evc_clk_diff(from, now); \
00131 }
00132 #else
00133 static EVC_CLK evc_clk_from(EVC_CLK from) \
00134 {
00135   EVC_CLK now = evc_clk_get(); \
00136     return evc_clk_diff(from, now); \
00137 }
00138 #endif
