00141 #define evc_clk_msec(clk) \
00142     ((int)((clk + (EVC_CLK_PER_MSEC/2))/EVC_CLK_PER_MSEC))
00143 #define evc_clk_sec(clk)  \
00144     ((int)((clk + (EVC_CLK_PER_SEC/2))/EVC_CLK_PER_SEC))
