00146 #define IFVCA_CLIP(n,min,max) (((n)>(max))? (max) : (((n)<(min))? (min) : (n)))
00147 #if REMOVE_WARNING
00148 int imgb_read(FILE * fp, EVC_IMGB * img)
00149 #else
00150 static int imgb_read(FILE * fp, EVC_IMGB * img)
00151 #endif
00152 {
00153     int f_w, f_h;
00154     int y_size, u_size, v_size;
00155 
00156     f_w = img->w[0];
00157     f_h = img->h[0];
00158 
00159     if(img->cs == EVC_COLORSPACE_YUV420)
00160     {
00161         y_size = f_w * f_h;
00162         u_size = v_size = (f_w >> 1) * (f_h >> 1);
00163 
00164         if(fread(img->a[0], 1, y_size, fp) != (unsigned)y_size)
00165         {
00166             return -1;
00167         }
00168         if(fread(img->a[1], 1, u_size, fp) != (unsigned)u_size)
00169         {
00170             return -1;
00171         }
00172         if(fread(img->a[2], 1, v_size, fp) != (unsigned)v_size)
00173         {
00174             return -1;
00175         }
00176     }
00177     else if(img->cs == EVC_COLORSPACE_YUV420_10LE)
00178     {
00179 
00180         y_size = f_w * f_h * sizeof(short);
00181         u_size = v_size = (f_w >> 1) * (f_h >> 1) * sizeof(short);
00182         if(fread(img->a[0], 1, y_size, fp) != (unsigned)y_size)
00183         {
00184             return -1;
00185         }
00186         if(fread(img->a[1], 1, u_size, fp) != (unsigned)u_size)
00187         {
00188             return -1;
00189         }
00190         if(fread(img->a[2], 1, v_size, fp) != (unsigned)v_size)
00191         {
00192             return -1;
00193         }
00194     }
00195     else
00196     {
00197         print("not supported color space\n");
00198         return -1;
00199     }
00200 
00201     return 0;
00202 }
00203 #if REMOVE_WARNING
00204 int imgb_write(char * fname, EVC_IMGB * img)
00205 #else
00206 static int imgb_write(char * fname, EVC_IMGB * img)
00207 #endif
00208 {
00209     unsigned char * p8;
00210     int             i, j, bd;
00211     FILE          * fp;
00212 
00213     fp = fopen(fname, "ab");
00214     if(fp == NULL)
00215     {
00216         print("cannot open file = %s\n", fname);
00217         return -1;
00218     }
00219     if(img->cs == EVC_COLORSPACE_YUV420_10LE)
00220     {
00221         bd = 2;
00222     }
00223     else if(img->cs == EVC_COLORSPACE_YUV420)
00224     {
00225         bd = 1;
00226     }
00227     else
00228     {
00229         print("cannot support the color space\n");
00230         return -1;
00231     }
00232 
00233     for(i = 0; i < 3; i++)
00234     {
00235         p8 = (unsigned char *)img->a[i] + (img->s[i] * img->y[i]) + (img->x[i] * bd);
00236 
00237         for(j = 0; j < img->h[i]; j++)
00238         {
00239             fwrite(p8, img->w[i] * bd, 1, fp);
00240             p8 += img->s[i];
00241         }
00242     }
00243     fclose(fp);
00244     return 0;
00245 }
00246 
00247 static void __imgb_cpy_plane(void *src, void *dst, int bw, int h, int s_src,
00248                              int s_dst)
00249 {
00250     int i;
00251     unsigned char *s, *d;
00252 
00253     s = (unsigned char*)src;
00254     d = (unsigned char*)dst;
00255 
00256     for(i = 0; i < h; i++)
00257     {
00258         memcpy(d, s, bw);
00259         s += s_src;
00260         d += s_dst;
00261     }
00262 }
00263 #if REMOVE_WARNING
00264 int write_data(char * fname, unsigned char * data, int size)
00265 #else
