00282 static void imgb_conv_8b_to_16b(EVC_IMGB * imgb_dst, EVC_IMGB * imgb_src,
00283                                 int shift)
00284 {
00285     int i, j, k;
00286 
00287     unsigned char * s;
00288     short         * d;
00289 
00290     for(i = 0; i < 3; i++)
00291     {
00292         s = imgb_src->a[i];
00293         d = imgb_dst->a[i];
00294 
00295         for(j = 0; j < imgb_src->h[i]; j++)
00296         {
00297             for(k = 0; k < imgb_src->w[i]; k++)
00298             {
00299                 d[k] = (short)(s[k] << shift);
00300             }
00301             s = s + imgb_src->s[i];
00302             d = (short*)(((unsigned char *)d) + imgb_dst->s[i]);
00303         }
00304     }
00305 }
00306 
00307 static void imgb_conv_16b_to_8b(EVC_IMGB * imgb_dst, EVC_IMGB * imgb_src,
00308                                 int shift)
00309 {
00310 
00311     int i, j, k, t0, add;
00312 
00313     short         * s;
00314     unsigned char * d;
00315 
00316     add = 1 << (shift - 1);
00317 
00318     for(i = 0; i < 3; i++)
00319     {
00320         s = imgb_src->a[i];
00321         d = imgb_dst->a[i];
00322 
00323         for(j = 0; j < imgb_src->h[i]; j++)
00324         {
00325             for(k = 0; k < imgb_src->w[i]; k++)
00326             {
00327                 t0 = ((s[k] + add) >> shift);
00328                 d[k] = (unsigned char)(IFVCA_CLIP(t0, 0, 255));
00329 
00330             }
00331             s = (short*)(((unsigned char *)s) + imgb_src->s[i]);
00332             d = d + imgb_dst->s[i];
00333         }
00334     }
00335 }
00336 #if REMOVE_WARNING
00337 void imgb_cpy(EVC_IMGB * dst, EVC_IMGB * src)
00338 #else
00339 static void imgb_cpy(EVC_IMGB * dst, EVC_IMGB * src)
00340 #endif
00341 {
00342     int i, bd;
00343 
00344     if(src->cs == dst->cs)
00345     {
00346         if(src->cs == EVC_COLORSPACE_YUV420_10LE) bd = 2;
00347         else bd = 1;
00348 
00349         for(i = 0; i < src->np; i++)
00350         {
00351             __imgb_cpy_plane(src->a[i], dst->a[i], bd*src->w[i], src->h[i],
00352                              src->s[i], dst->s[i]);
00353 
00354         }
00355     }
00356     else if(src->cs == EVC_COLORSPACE_YUV420 &&
00357             dst->cs == EVC_COLORSPACE_YUV420_10LE)
00358     {
00359         imgb_conv_8b_to_16b(dst, src, 2);
00360     }
00361     else if(src->cs == EVC_COLORSPACE_YUV420_10LE &&
00362             dst->cs == EVC_COLORSPACE_YUV420)
00363     {
00364         imgb_conv_16b_to_8b(dst, src, 2);
00365     }
00366     else
00367     {
00368         v0print("ERROR: unsupported image copy\n");
00369         return;
00370     }
00371     for(i = 0; i < 4; i++)
00372     {
00373         dst->ts[i] = src->ts[i];
00374     }
00375 }
