00377 static void imgb_free(EVC_IMGB * imgb)
00378 {
00379     int i;
00380     for(i = 0; i < EVC_IMGB_MAX_PLANE; i++)
00381     {
00382         if(imgb->baddr[i]) free(imgb->baddr[i]);
00383     }
00384     free(imgb);
00385 }
