00387 EVC_IMGB * imgb_alloc(int w, int h, int cs)
00388 {
00389     int i;
00390     EVC_IMGB * imgb;
00391 
00392     imgb = (EVC_IMGB *)malloc(sizeof(EVC_IMGB));
00393     if(imgb == NULL)
00394     {
00395         v0print("cannot create image buffer\n");
00396         return NULL;
00397     }
00398     memset(imgb, 0, sizeof(EVC_IMGB));
00399 
00400     if(cs == EVC_COLORSPACE_YUV420)
00401     {
00402         for(i = 0; i < 3; i++)
00403         {
00404             imgb->w[i] = imgb->aw[i] = imgb->s[i] = w;
00405             imgb->h[i] = imgb->ah[i] = imgb->e[i] = h;
00406             imgb->bsize[i] = imgb->s[i] * imgb->e[i];
00407 
00408             imgb->a[i] = imgb->baddr[i] = malloc(imgb->bsize[i]);
00409             if(imgb->a[i] == NULL)
00410             {
00411                 v0print("cannot allocate picture buffer\n");
00412                 return NULL;
00413             }
00414 
00415             if(i == 0)
00416             {
00417                 w = (w + 1) >> 1; h = (h + 1) >> 1;
00418             }
00419         }
00420         imgb->np = 3;
00421     }
00422     else if(cs == EVC_COLORSPACE_YUV420_10LE)
00423     {
00424         for(i = 0; i < 3; i++)
00425         {
00426             imgb->w[i] = imgb->aw[i] = w;
00427             imgb->s[i] = w * sizeof(short);
00428             imgb->h[i] = imgb->ah[i] = imgb->e[i] = h;
00429             imgb->bsize[i] = imgb->s[i] * imgb->e[i];
00430 
00431             imgb->a[i] = imgb->baddr[i] = malloc(imgb->bsize[i]);
00432             if(imgb->a[i] == NULL)
00433             {
00434                 v0print("cannot allocate picture buffer\n");
00435                 return NULL;
00436             }
00437 
00438             if(i == 0)
00439             {
00440                 w = (w + 1) >> 1; h = (h + 1) >> 1;
00441             }
00442         }
00443         imgb->np = 3;
00444     }
00445 #if HDR_METRIC
00446     else if (cs == EVC_COLORSPACE_YUV444_10LE)
00447     {
00448         for (i = 0; i < 3; i++)
00449         {
00450             imgb->w[i] = imgb->aw[i] = w;
00451             imgb->s[i] = w * sizeof(float);
00452             imgb->h[i] = imgb->ah[i] = imgb->e[i] = h;
00453             imgb->bsize[i] = imgb->s[i] * imgb->e[i];
00454 
00455             imgb->a[i] = imgb->baddr[i] = malloc(imgb->bsize[i]);
00456             if (imgb->a[i] == NULL)
00457             {
00458                 v0print("cannot allocate picture buffer\n");
00459                 return NULL;
00460             }
00461         }
00462         imgb->np = 3;
00463     }
00464 #endif
00465     else
00466     {
00467         v0print("unsupported color space\n");
00468         if(imgb)free(imgb);
00469         return NULL;
00470     }
00471 
00472     imgb->cs = cs;
00473     return imgb;
00474 }
